using UnityEngine;

namespace RallyX.Tracks
{
    /// <summary>
    /// An alternative route, such as a shortcut, that leaves the main <see cref="TrackPath"/> and rejoins it further on.
    /// Holds its own baked centreline in driving order, from where it leaves to where it rejoins. Generated by the
    /// track builder.
    /// </summary>
    [DisallowMultipleComponent]
    public sealed class TrackBranch : MonoBehaviour
    {
        [SerializeField] private TrackPath mainPath;
        [SerializeField, HideInInspector] private Vector3[] points = System.Array.Empty<Vector3>();
        [SerializeField, HideInInspector] private float[] widths = System.Array.Empty<float>();

        public TrackPath MainPath => mainPath;
        public int Count => points.Length;

        public Vector3 GetPoint(int index) => points[Mathf.Clamp(index, 0, points.Length - 1)];
        public float GetWidth(int index) => widths[Mathf.Clamp(index, 0, widths.Length - 1)];

        /// <summary>Distance along the main path where the branch leaves it.</summary>
        public float LeaveDistance => mainPath.FindClosestDistance(points[0]);

        /// <summary>Distance along the main path where the branch rejoins it.</summary>
        public float RejoinDistance => mainPath.FindClosestDistance(points[points.Length - 1]);

        public void SetSamples(TrackPath main, Vector3[] newPoints, float[] newWidths)
        {
            mainPath = main;
            points = newPoints;
            widths = newWidths;
        }

        private void OnDrawGizmosSelected()
        {
            Gizmos.color = new Color(0.9f, 0.5f, 0.1f);
            for (int i = 0; i < points.Length - 1; i++)
                Gizmos.DrawLine(points[i] + Vector3.up * 0.5f, points[i + 1] + Vector3.up * 0.5f);
        }
    }
}
